const account = require('../scripts/routes/cross_border/advertiser_account_status_snapshot');
const hourly = require('../scripts/routes/cross_border/gmvmax_campaign_hourly_performance');
const interval = require('../scripts/routes/cross_border/gmvmax_campaign_performance_interval');
const localHourly = require('../scripts/routes/local/gmvmax_campaign_hourly_performance');
