const SELLER = '7494671404273272171'; const ADVERTISER = '7645257137211572244'; const BC = '7657498635260936200';
const BATCH_IDS = ['advertiser_account_status_snapshot', 'gmvmax_campaign_hourly_performance', 'gmvmax_campaign_performance', 'gmvmax_campaign_current_configuration_snapshot', 'gmvmax_campaign_change_log', 'gmvmax_campaign_recommendation_snapshot'];
function harness(fetch) { const page = { url: () => 'https://seller.tiktokshopglobalselling.com/homepage', ...(fetch ? { request:{ fetch } } : {}) }; const context = { pages: () => [page] }; const browser = { isConnected: () => true, contexts: () => [context] }; return { browser, context, dependencies: { browser, browserContext: context, skillRoot: path.resolve(__dirname, '..'), clock: () => new Date('2026-08-21T00:00:00Z') } }; }
function fetchResponse(url, body, status=200) { return { url:()=>url, status:()=>status, body:async()=>Buffer.from(JSON.stringify(body)) }; }
function input(spec, outputDir, extra = {}) { return { reportSpec: spec, providerSpec: spec.providers?.cross_border, outputDir, startDate: '2026-08-20', endDate: '2026-08-20', b: { seller_page_url: 'https://seller.tiktokshopglobalselling.com/homepage' }, shop: { seller_id: SELLER, provider_id: 'cross_border' }, advertiserId: ADVERTISER, advertiserName: 'Advertiser', advertiserCurrency: 'USD', businessCenterId: BC, ...extra }; }
function context(shopRoot, overrides = {}) { return { request_id: 'batch-g', shop_root: shopRoot, shop_name: 'Shop', shop_id: SELLER, seller_id: SELLER, provider_id: 'cross_border', advertiser_id: ADVERTISER, advertiser_name: 'Advertiser', business_center_id: BC, campaign_ref: null, product_ref: null, start_date: '2026-08-20', end_date: '2026-08-20', ...overrides }; }
function campaign(overrides = {}) { return { campaign_id: '100', campaign_name: 'Campaign', cost: 1, show_cnt: 10, click_cnt: 1, ctr: 10, onsite_roi2_shopping_sku: 2, cost_per_onsite_roi2_shopping_sku: 0.5, onsite_roi2_shopping_value: 4, onsite_roi2_shopping: 4, extra_currency: 'PHP', ...overrides }; }
function pageBody(rows = [campaign()]) { return { code: 0, data: { table: rows, pagination: { total_count: rows.length, page_count: rows.length ? 1 : 0, page: 1 } } }; }
function hourlyChart(names = ['cost'], value = (name) => name) { return { code:0, data:{ chart:{ categories:Array.from({length:24},(_,index)=>`${String(index).padStart(2,'0')}:00`), series:names.map((name)=>({name,data:Array.from({length:24},(_,index)=>value(name,index))})) } } }; }
function ok(body) { return { http_status: 200, body }; }

test('real MD exposes the current Batch G reports within the provider-only catalog', () => {
  const loaded = loadReportMd(); assert.equal(Object.keys(loaded.specs).length, 23);
  for (const reportId of BATCH_IDS) assert.equal(resolveReportIds(`report:${reportId}`, loaded)[0], reportId);
  const declaredEntryCount = Object.values(loaded.specs).filter((spec) => spec.enabled)
    .reduce((total, spec) => total + Object.keys(spec.providers).length, 0);
  assert.equal(declaredEntryCount, 46);
  assert.deepEqual(Object.keys(loaded.specs.inventory_snapshot.providers), ['cross_border', 'local']);
  for (const alias of ['all', 'default']) assert.throws(() => resolveReportIds(alias, loaded), { code: 'report_alias_unknown' });
  const hourlySpec=loaded.specs.gmvmax_campaign_hourly_performance;
  assert.equal(hourlySpec.runner,undefined);assert.deepEqual(Object.keys(hourlySpec.providers),['cross_border','local']);assert.equal(hourlySpec.providers.cross_border.retry_policy,undefined);
  const commonSource=fs.readFileSync(path.join(__dirname,'..','scripts','routes','common','gmvmax_campaign_hourly_performance_v3.js'),'utf8');
  assert.doesNotMatch(commonSource,/\brun\b|\.request\b|requestJson|\.fetch\(|endpoint|provider|campaignBody|collectCampaign/u);
  const runnerSource=fs.readFileSync(path.join(__dirname,'..',hourlySpec.providers.cross_border.runner),'utf8');assert.doesNotMatch(runnerSource,/gmvmax-api-v3/u);
  const invalid = structuredClone(hourlySpec); delete invalid.providers.cross_border.api_contract.hourly_endpoint;
  assert.throws(() => hourly.validateSpec(invalid,invalid.providers.cross_border,{ skillRoot: path.resolve(__dirname, '..') }), { code: 'campaign_hourly_spec_invalid' });
  const intervalSpec=loaded.specs.gmvmax_campaign_performance;
  assert.equal(intervalSpec.runner,undefined);assert.deepEqual(Object.keys(intervalSpec.providers),['cross_border','local']);assert.equal(intervalSpec.providers.cross_border.retry_policy,undefined);
  const intervalCommon=fs.readFileSync(path.join(__dirname,'..','scripts','routes','common','gmvmax_campaign_performance_interval_v3.js'),'utf8');assert.doesNotMatch(intervalCommon,/\brun\b|\.request\b|requestJson|\.fetch\(|endpoint|provider|pagination|selectCampaign|gmvmax-api-v3/u);
  const intervalRunner=fs.readFileSync(path.join(__dirname,'..',intervalSpec.providers.cross_border.runner),'utf8');assert.doesNotMatch(intervalRunner,/gmvmax-api-v3|gmvmax_campaign_hourly/u);
  const configurationSpec=loaded.specs.gmvmax_campaign_current_configuration_snapshot;assert.equal(configurationSpec.runner,undefined);assert.deepEqual(Object.keys(configurationSpec.providers),['cross_border','local']);assert.equal(configurationSpec.providers.cross_border.retry_policy,undefined);
  const configurationCommonSource=fs.readFileSync(path.join(__dirname,'..','scripts','routes','common','gmvmax_campaign_current_configuration_snapshot_v3.js'),'utf8');assert.doesNotMatch(configurationCommonSource,/\brun\b|\.request\b|\.fetch\(|endpoint|provider|pagination|selectCampaign|writeArtifact|gmvmax-api-v3/u);
  const configurationRunnerSource=fs.readFileSync(path.join(__dirname,'..',configurationSpec.providers.cross_border.runner),'utf8');assert.doesNotMatch(configurationRunnerSource,/gmvmax-api-v3|gmvmax_campaign_(?:daily|hourly|performance_interval).*\.js/u);
  const recommendationSpec=loaded.specs.gmvmax_campaign_recommendation_snapshot;assert.equal(recommendationSpec.runner,undefined);assert.deepEqual(Object.keys(recommendationSpec.providers),['cross_border','local']);assert.equal(recommendationSpec.providers.cross_border.retry_policy,undefined);
  const recommendationCommonSource=fs.readFileSync(path.join(__dirname,'..','scripts','routes','common','gmvmax_campaign_recommendation_snapshot_v3.js'),'utf8');assert.doesNotMatch(recommendationCommonSource,/\brun\b|\.request\b|\.fetch\(|endpoint|provider|pagination|selectCampaign|writeArtifact|gmvmax-api-v3/u);
  const recommendationRunnerSource=fs.readFileSync(path.join(__dirname,'..',recommendationSpec.providers.cross_border.runner),'utf8');assert.doesNotMatch(recommendationRunnerSource,/gmvmax-api-v3|gmvmax_campaign_(?:daily|hourly|performance_interval|current_configuration).*\.js/u);
for(const [reportId,runner,code] of [['advertiser_account_status_snapshot',account,'advertiser_account_spec_invalid']]){const spec=loaded.specs[reportId];assert.equal(spec.runner,undefined);assert.deepEqual(Object.keys(spec.providers),['cross_border','local']);assert.equal(spec.providers.cross_border.retry_policy,undefined);const common=fs.readFileSync(path.join(__dirname,'..','scripts','routes','common',`${reportId}_v3.js`),'utf8');assert.doesNotMatch(common,/\brun\b|\.request\b|\.fetch\(|endpoint|provider|pagination|selectCampaign|writeArtifact|gmvmax-api-v3/u);const source=fs.readFileSync(path.join(__dirname,'..',spec.providers.cross_border.runner),'utf8');assert.doesNotMatch(source,/gmvmax-api-v3|gmvmax_campaign_(?:daily|hourly|performance_interval).*\.js/u);const extensible=structuredClone(spec);extensible.metadata=true;extensible.providers.cross_border.metadata=true;extensible.providers.cross_border.api_contract.metadata=true;runner.validateSpec(extensible,extensible.providers.cross_border,{skillRoot:path.resolve(__dirname,'..')});const invalid=structuredClone(spec);delete invalid.providers.cross_border.response_origin;assert.throws(()=>runner.validateSpec(invalid,invalid.providers.cross_border,{skillRoot:path.resolve(__dirname,'..')}),{code});}
});

test('change log API failures preserve endpoint and response diagnostics',async(t)=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-change-diagnostics-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_change_log,c=spec.providers.cross_border.api_contract;const live=harness(async(url)=>fetchResponse(url,{code:7,data:{}}));await assert.rejects(()=>changeLog.run(input(spec,path.join(root,'business')),{...live.dependencies,discoverCampaigns:async()=>[campaign()]}),(error)=>{assert.equal(error.code,'campaign_change_log_api_error');assert.equal(error.diagnostics.stage,'change');assert.equal(error.diagnostics.path,c.change_endpoint);assert.equal(error.diagnostics.http_status,200);assert.equal(error.diagnostics.business_code,7);return true;});});

test('GMV campaign query names constants timeout and response paths are driven by MD', async () => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-sentinel-')); const spec=structuredClone(loadReportMd().specs.gmvmax_campaign_performance); const live=harness();
  const provider=spec.providers.cross_border;provider.metadata=true;provider.api_contract.metadata={ignored:true};provider.api_contract.campaign_request.future_payload='preserved';provider.campaign_request_fields={start:'sentinel_start',end:'sentinel_end',page:'sentinel_page'};
  provider.api_contract.request_query={sentinel_locale:'sentinel-value',seller:'sentinel_seller',advertiser:'sentinel_advertiser',timeout_ms:4321};
  provider.api_contract.campaign_response={records:['sentinel','rows'],pagination:['sentinel','page_info'],total:'count',page_count:'pages',page:'index',id:'sentinel_id',name:'sentinel_name'};
  let observed; const result=await interval.run(input(spec,path.join(root,'stage')),{...live.dependencies,request:async(_page,request)=>{observed=request;return ok({code:0,sentinel:{rows:[{sentinel_id:'100',sentinel_name:'Campaign',cost:1}],page_info:{count:1,pages:1,index:1}}});}});
  assert.equal(observed.search_params.sentinel_locale,'sentinel-value'); assert.equal(observed.search_params.sentinel_seller,SELLER); assert.equal(observed.search_params.sentinel_advertiser,ADVERTISER); assert.equal(observed.timeout_ms,4321); assert.equal(result.artifacts[0].campaign_id,'100');
  assert.equal(observed.body.sentinel_start,'2026-08-20');assert.equal(observed.body.sentinel_end,'2026-08-20');assert.equal(observed.body.sentinel_page,1);assert.equal(observed.body.future_payload,'preserved');assert.equal(observed.body.filters,undefined);
  const invalid=structuredClone(spec);delete invalid.providers.cross_border.api_contract.campaign_response.records;assert.throws(()=>interval.validateSpec(invalid,invalid.providers.cross_border),{code:'campaign_interval_spec_invalid'});
});

test('hourly campaign and metric payload fields are driven by selected provider MD', () => {
  const spec=structuredClone(loadReportMd().specs.gmvmax_campaign_hourly_performance);
  const provider=spec.providers.cross_border;
  provider.metadata={ignored:true};provider.api_contract.metadata=true;provider.api_contract.campaign_request.future_payload='campaign-extra';provider.api_contract.hourly_request.future_payload='hourly-extra';
  provider.campaign_request_fields={start:'sentinel_start',end:'sentinel_end',page:'sentinel_page'};
  provider.api_contract.hourly_request_fields={start:'sentinel_start',end:'sentinel_end',campaign_ids:'sentinel_ids'};
  hourly.validateSpec(spec,provider);
  const campaignBody=hourly.campaignBody(provider,'2026-08-20',3);const metricBody=hourly.hourlyBody(provider,'1870130072117617','2026-08-20');
  assert.equal(campaignBody.sentinel_start,'2026-08-20');assert.equal(campaignBody.sentinel_page,3);assert.equal(campaignBody.future_payload,'campaign-extra');assert.equal(campaignBody.filters,undefined);
  assert.equal(metricBody.sentinel_start,'2026-08-20');assert.deepEqual(metricBody.sentinel_ids,[1870130072117617]);assert.equal(metricBody.future_payload,'hourly-extra');
  assert.throws(()=>hourly.hourlyBody(provider,'9007199254740993','2026-08-20'),{code:'campaign_universe_count_mismatch'});
  for(const queryList of [[],['cost','cost'],['']]){const invalid=structuredClone(spec);invalid.providers.cross_border.api_contract.hourly_request.query_list=queryList;assert.throws(()=>hourly.validateSpec(invalid,invalid.providers.cross_border),{code:'campaign_hourly_spec_invalid'});}
});

test('advertiser account binds five official methods and frozen identities and fails closed', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-account-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.advertiser_account_status_snapshot,provider=spec.providers.cross_border,calls=[];
  function body(name){if(name==='payment')return{code:0,data:{adv_info_vo:{id:ADVERTISER},future:'payment'}};if(name==='authorization')return{code:0,data:{autho_info_list:[{adv_id:ADVERTISER,future:true}]}};return{code:0,data:{future:name}};}
  function live(mutate){return harness(async(url,options)=>{const entry=Object.entries(provider.api_contract.sources).find(([,value])=>value.endpoint===new URL(url).pathname);assert.ok(entry);const[name,source]=entry;calls.push({name,url:new URL(url),options});const value=mutate?.(name,body(name))||body(name);return fetchResponse(url,value);});}
  const session=live();const result=await account.run(input(spec,path.join(root,'stage')),session.dependencies);assert.equal(result.status,'success');assert.equal(result.row_count,1);assert.deepEqual(calls.map((item)=>[item.name,item.options.method]),[['payment','POST'],['ownership','GET'],['billing','GET'],['billing_options','POST'],['authorization','POST']]);
  const accountSheet=require('../scripts/common/xlsx_first_sheet').readFirstWorksheet(fs.readFileSync(result.output_file));const snapshot=JSON.parse(accountSheet.rows[1][3]);assert.deepEqual(Object.keys(snapshot),['authorization','billing','billing_options','frozen_identity','ownership','payment']);assert.equal(snapshot.frozen_identity.advertiser_id,ADVERTISER);assert.equal(snapshot.frozen_identity.seller_id,SELLER);for(const name of ['payment','ownership','billing','billing_options','authorization'])assert.equal(snapshot[name].future,name==='authorization'?undefined:name);
  const f=provider.api_contract.request_fields;assert.equal(calls[0].options.data[f.context][f.advertiser],ADVERTISER);assert.equal(calls[0].options.data[f.context][f.business_center],BC);assert.equal(calls[1].url.searchParams.get(f.advertiser),ADVERTISER);assert.equal(calls[2].url.searchParams.get(f.advertiser),ADVERTISER);assert.equal(calls[4].options.data[f.query_list][0][f.shop_id],SELLER);
  for(const [name,mutate] of [['payment',(source,value)=>source==='payment'?{...value,data:{adv_info_vo:{id:'9'}}}:value],['authorization',(source,value)=>source==='authorization'?{...value,data:{autho_info_list:[{adv_id:'9'}]}}:value]]){const bad=live(mutate);await assert.rejects(()=>account.run(input(spec,path.join(root,name)),bad.dependencies),{code:'advertiser_account_identity_mismatch'});}
  const emptyAuthorization=live((source,value)=>source==='authorization'?{...value,data:{autho_info_list:[]}}:value);await assert.rejects(()=>account.run(input(spec,path.join(root,'authorization-empty')),emptyAuthorization.dependencies),{code:'advertiser_account_identity_mismatch'});
  for(const origin of ['https://evil.example','https://seller-ph.tiktok.com']){const redirected=harness(async(url)=>fetchResponse(`${origin}${new URL(url).pathname}`,body(Object.entries(provider.api_contract.sources).find(([,v])=>v.endpoint===new URL(url).pathname)[0])));await assert.rejects(()=>account.run(input(spec,path.join(root,new URL(origin).hostname)),redirected.dependencies),{code:'seller_origin_mismatch'});}
  for(const [name,responseBody,status,code] of [['shape',{code:0,data:null},200,'advertiser_account_shape_invalid'],['api',{code:1,data:{}},200,'advertiser_account_api_error'],['http',{code:0,data:{}},500,'advertiser_account_api_error']]){const broken=harness(async(url)=>fetchResponse(url,responseBody,status));await assert.rejects(()=>account.run(input(spec,path.join(root,name)),broken.dependencies),{code});}
  let connected=true;let disconnected;disconnected=harness(async()=>{connected=false;throw new Error('transport');});const browser={isConnected:()=>connected,contexts:()=>[disconnected.context]};await assert.rejects(()=>account.run(input(spec,path.join(root,'disconnect')),{...disconnected.dependencies,browser}),{code:'browser_disconnected'});
});

test('configuration snapshot uses one captured date and MD-driven filtered campaign payload', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-configuration-sentinel-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=structuredClone(loadReportMd().specs.gmvmax_campaign_current_configuration_snapshot);const provider=spec.providers.cross_border;const contract=provider.api_contract;
  spec.metadata=true;provider.metadata={ignored:true};contract.metadata=true;contract.campaign_request.future_payload='preserved';provider.campaign_request_fields={start:'sentinel_start',end:'sentinel_end',page:'sentinel_page'};let clockCalls=0;const observed=[];
  const live=harness(async(url,options)=>{observed.push({url,options});if(new URL(url).pathname===contract.campaign_endpoint)return fetchResponse(url,pageBody());return fetchResponse(url,{code:0,data:{campaign_info:{campaign_id:'100'},ad_info:{campaign_id:'100',shop_id:SELLER},future_configuration:{preserved:true}}});});live.dependencies.clock=()=>{clockCalls+=1;return new Date('2026-08-22T12:00:00Z');};
  const result=await configuration.run(input(spec,path.join(root,'stage')),live.dependencies);assert.equal(clockCalls,1);assert.equal(result.artifacts[0].captured_date,'2026-08-22');assert.equal(observed[0].options.data.sentinel_start,'2026-08-22');assert.equal(observed[0].options.data.sentinel_end,'2026-08-22');assert.equal(observed[0].options.data.sentinel_page,1);assert.equal(observed[0].options.data.future_payload,'preserved');assert.deepEqual(observed[0].options.data.filters,[{field:'campaign_status',in_field_values:['no_delete'],filter_type:0}]);assert.equal(observed[0].options.data.current_filters,undefined);assert.equal(observed[1].options.method,'GET');assert.equal('data'in observed[1].options,false);
  const sheet=require('../scripts/common/xlsx_first_sheet').readFirstWorksheet(fs.readFileSync(result.artifacts[0].output_file));assert.equal(JSON.parse(sheet.rows[1][3]).future_configuration.preserved,true);
  const invalid=structuredClone(spec);delete invalid.providers.cross_border.api_contract.detail_seller_id_paths;assert.throws(()=>configuration.validateSpec(invalid,invalid.providers.cross_border),{code:'campaign_configuration_spec_invalid'});
});

test('configuration snapshot completes campaign pagination, selection, and trusted zero', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-configuration-pages-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_current_configuration_snapshot;const provider=spec.providers.cross_border;let execution=0;
  async function execute(extra={},pageFactory=(page)=>({code:0,data:{table:[campaign({campaign_id:String(page),campaign_name:`Campaign ${page}`})],pagination:{total_count:2,page_count:2,page}}})){execution+=1;let detailCalls=0;const live=harness(async(url,options)=>{const target=new URL(url);if(target.pathname===provider.api_contract.campaign_endpoint)return fetchResponse(url,pageFactory(options.data.page));detailCalls+=1;const id=target.searchParams.get(provider.api_contract.detail_request_field);return fetchResponse(url,{code:0,data:{campaign_info:{campaign_id:id},ad_info:{campaign_id:id,shop_id:SELLER},extra:{id}}});});const result=await configuration.run(input(spec,path.join(root,`stage-${execution}`),extra),live.dependencies);return{result,detailCalls};}
  const all=await execute();assert.equal(all.result.artifacts.length,2);assert.equal(all.detailCalls,2);const explicit=await execute({campaignRef:'2'});assert.equal(explicit.result.artifacts.length,1);assert.equal(explicit.result.artifacts[0].campaign_id,'2');assert.equal(explicit.detailCalls,1);
  await assert.rejects(()=>execute({campaignRef:'9'}),{code:'explicit_campaign_not_found_in_report_universe'});await assert.rejects(()=>execute({campaignRef:'Same'},()=>({code:0,data:{table:[campaign({campaign_id:'1',campaign_name:'Same'}),campaign({campaign_id:'2',campaign_name:'Same'})],pagination:{total_count:2,page_count:1,page:1}}})),{code:'explicit_campaign_ambiguous'});
  for(const [name,factory,code] of [['total-drift',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:page===1?2:3,page_count:2,page}}}),'campaign_universe_pagination_changed'],['pages-drift',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:2,page_count:page===1?2:3,page}}}),'campaign_universe_pagination_changed'],['wrong-page',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:2,page_count:2,page:page+1}}}),'campaign_universe_shape_invalid'],['duplicate',(page)=>({code:0,data:{table:[campaign({campaign_id:'1'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch'],['invalid-id',(page)=>({code:0,data:{table:[campaign({campaign_id:page===1?'bad':'2'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch'],['empty-name',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page),campaign_name:page===1?'':'ok'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch']])await assert.rejects(()=>execute({},factory),{code},name);
  const zero=await execute({},()=>pageBody([]));assert.equal(zero.result.status,'no_data');assert.deepEqual(zero.result.artifacts,[]);assert.equal(zero.detailCalls,0);
});

test('configuration detail requires every campaign and seller identity path plus object data', () => {
  const contract=loadReportMd().specs.gmvmax_campaign_current_configuration_snapshot.providers.cross_border.api_contract;const id='1870130072117617';const valid={code:0,data:{campaign_info:{campaign_id:id},ad_info:{campaign_id:id,shop_id:SELLER},future:true}};assert.equal(configuration.validateDetail(valid,contract,id,SELLER).future,true);
  for(const mutate of [(value)=>delete value.data.campaign_info.campaign_id,(value)=>value.data.campaign_info.campaign_id='9',(value)=>delete value.data.ad_info.campaign_id,(value)=>value.data.ad_info.campaign_id='9',(value)=>delete value.data.ad_info.shop_id,(value)=>value.data.ad_info.shop_id='9']){const value=structuredClone(valid);mutate(value);assert.throws(()=>configuration.validateDetail(value,contract,id,SELLER),{code:'campaign_configuration_identity_mismatch'});}
  assert.throws(()=>configuration.validateDetail({code:0,data:[]},contract,id,SELLER),{code:'campaign_configuration_shape_invalid'});const nonObject=structuredClone(valid);nonObject.data='bad';assert.throws(()=>configuration.validateDetail(nonObject,contract,id,SELLER),{code:'campaign_configuration_shape_invalid'});
});

test('configuration binds campaign and detail final URLs with disconnect fatal priority', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-configuration-origin-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_current_configuration_snapshot;const provider=spec.providers.cross_border;const contract=provider.api_contract;let execution=0;
  async function execute(targetEndpoint,mutate,disconnect=false){execution+=1;let connected=true;const page={url:()=>`${provider.response_origin}/homepage`,request:{fetch:async(url,options)=>{const original=new URL(url);const final=new URL(url);if(original.pathname===targetEndpoint)mutate?.(final);if(disconnect)connected=false;const body=original.pathname===contract.campaign_endpoint?pageBody():{code:0,data:{campaign_info:{campaign_id:'100'},ad_info:{campaign_id:'100',shop_id:SELLER}}};return fetchResponse(final.href,body);}}};const context={pages:()=>[page]};const browser={isConnected:()=>connected,contexts:()=>[context]};return configuration.run(input(spec,path.join(root,`stage-${execution}`)),{browser,browserContext:context,skillRoot:path.resolve(__dirname,'..'),clock:()=>new Date('2026-08-21T00:00:00Z')});}
  for(const endpoint of [contract.campaign_endpoint,contract.detail_endpoint]){for(const origin of ['https://evil.example','https://seller-ph.tiktok.com'])await assert.rejects(()=>execute(endpoint,(url)=>{const changed=new URL(origin);url.protocol=changed.protocol;url.host=changed.host;}),{code:'seller_origin_mismatch'});await assert.rejects(()=>execute(endpoint,(url)=>{url.pathname='/wrong';}),{code:'seller_origin_mismatch'});for(const field of [contract.request_query.seller,contract.request_query.advertiser]){await assert.rejects(()=>execute(endpoint,(url)=>url.searchParams.delete(field)),{code:'provider_binding_invalid'});await assert.rejects(()=>execute(endpoint,(url)=>url.searchParams.set(field,'9')),{code:'provider_binding_invalid'});}}
  await assert.rejects(()=>execute(contract.detail_endpoint,(url)=>url.searchParams.delete(contract.detail_request_field)),{code:'campaign_configuration_identity_mismatch'});await assert.rejects(()=>execute(contract.detail_endpoint,(url)=>url.searchParams.set(contract.detail_request_field,'9')),{code:'campaign_configuration_identity_mismatch'});await assert.rejects(()=>execute(contract.campaign_endpoint,null,true),{code:'browser_disconnected'});
});

test('recommendation snapshot preserves MD-driven campaign payload and two-table semantics', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-recommendation-contract-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=structuredClone(loadReportMd().specs.gmvmax_campaign_recommendation_snapshot);const provider=spec.providers.cross_border;const contract=provider.api_contract;
  spec.metadata=true;provider.metadata={ignored:true};contract.metadata=true;contract.campaign_request.future_payload='preserved';provider.campaign_request_fields={start:'sentinel_start',end:'sentinel_end',page:'sentinel_page'};let clockCalls=0;const observed=[];const item={apply_entity:{id:'100'},content:{meta:{campaign_id:'100'}},future_item:{preserved:true}};const summary={future_summary:{preserved:true}};
  const live=harness(async(url,options)=>{observed.push({url,options});return new URL(url).pathname===contract.campaign_endpoint?fetchResponse(url,pageBody()):fetchResponse(url,{code:0,data:{items:[item],summary}});});live.dependencies.clock=()=>{clockCalls+=1;return new Date('2026-08-22T00:00:00Z');};const result=await recommendation.run(input(spec,path.join(root,'success')),live.dependencies);
  assert.equal(clockCalls,1);assert.deepEqual(result.artifacts.map((artifact)=>artifact.logical_table),['items','summary']);assert.ok(result.artifacts.every((artifact)=>artifact.status==='success'));assert.equal(observed[0].options.data.sentinel_start,'2026-08-22');assert.equal(observed[0].options.data.sentinel_end,'2026-08-22');assert.equal(observed[0].options.data.sentinel_page,1);assert.equal(observed[0].options.data.future_payload,'preserved');assert.deepEqual(observed[0].options.data.filters,[{field:'campaign_status',in_field_values:['no_delete'],filter_type:0}]);assert.equal(observed[0].options.data.current_filters,undefined);
  const itemSheet=require('../scripts/common/xlsx_first_sheet').readFirstWorksheet(fs.readFileSync(result.artifacts[0].output_file));const summarySheet=require('../scripts/common/xlsx_first_sheet').readFirstWorksheet(fs.readFileSync(result.artifacts[1].output_file));assert.equal(JSON.parse(itemSheet.rows[1][1])[0].future_item.preserved,true);assert.equal(JSON.parse(summarySheet.rows[1][1]).future_summary.preserved,true);assert.equal(itemSheet.rows[1][2],'USD');assert.equal(summarySheet.rows[1][2],'USD');
  const zeroLive=harness(async(url)=>new URL(url).pathname===contract.campaign_endpoint?fetchResponse(url,pageBody()):fetchResponse(url,{code:0,data:{items:[],summary:{diagnosis:true}}}));const zero=await recommendation.run(input(spec,path.join(root,'zero')),zeroLive.dependencies);assert.equal(zero.status,'no_data');assert.deepEqual(zero.artifacts.map((artifact)=>artifact.status),['no_data','no_data']);assert.ok(zero.artifacts.every((artifact)=>artifact.row_count===0));
  const invalid=structuredClone(spec);delete invalid.providers.cross_border.api_contract.item_campaign_id_paths;assert.throws(()=>recommendation.validateSpec(invalid,invalid.providers.cross_border),{code:'campaign_recommendation_spec_invalid'});
});

test('recommendation campaign universe paginates completely and selection fails closed', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-recommendation-pages-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_recommendation_snapshot;const provider=spec.providers.cross_border;let execution=0;
  async function execute(extra={},pageFactory=(page)=>({code:0,data:{table:[campaign({campaign_id:String(page),campaign_name:`Campaign ${page}`})],pagination:{total_count:2,page_count:2,page}}})){execution+=1;let recommendationCalls=0;const live=harness(async(url,options)=>{const target=new URL(url);if(target.pathname===provider.api_contract.campaign_endpoint)return fetchResponse(url,pageFactory(options.data.page));recommendationCalls+=1;const id=target.searchParams.get(provider.api_contract.recommendation_request_fields.campaign);return fetchResponse(url,{code:0,data:{items:[{apply_entity:{id},content:{meta:{campaign_id:id}}}],summary:{id}}});});const result=await recommendation.run(input(spec,path.join(root,`stage-${execution}`),extra),live.dependencies);return{result,recommendationCalls};}
  const all=await execute();assert.equal(all.result.artifacts.length,4);assert.equal(all.recommendationCalls,2);const explicit=await execute({campaignRef:'2'});assert.equal(explicit.result.artifacts.length,2);assert.equal(explicit.recommendationCalls,1);await assert.rejects(()=>execute({campaignRef:'9'}),{code:'explicit_campaign_not_found_in_report_universe'});await assert.rejects(()=>execute({campaignRef:'Same'},()=>({code:0,data:{table:[campaign({campaign_id:'1',campaign_name:'Same'}),campaign({campaign_id:'2',campaign_name:'Same'})],pagination:{total_count:2,page_count:1,page:1}}})),{code:'explicit_campaign_ambiguous'});
  for(const [name,factory,code] of [['total-drift',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:page===1?2:3,page_count:2,page}}}),'campaign_universe_pagination_changed'],['pages-drift',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:2,page_count:page===1?2:3,page}}}),'campaign_universe_pagination_changed'],['wrong-page',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page)})],pagination:{total_count:2,page_count:2,page:page+1}}}),'campaign_universe_shape_invalid'],['duplicate',(page)=>({code:0,data:{table:[campaign({campaign_id:'1'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch'],['invalid',(page)=>({code:0,data:{table:[campaign({campaign_id:page===1?'bad':'2'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch'],['empty-name',(page)=>({code:0,data:{table:[campaign({campaign_id:String(page),campaign_name:page===1?'':'ok'})],pagination:{total_count:2,page_count:2,page}}}),'campaign_universe_count_mismatch']])await assert.rejects(()=>execute({},factory),{code},name);
  const zero=await execute({},()=>pageBody([]));assert.equal(zero.result.status,'no_data');assert.deepEqual(zero.result.artifacts,[]);assert.equal(zero.recommendationCalls,0);
});

test('recommendation validates response item identity and both request final URLs', async (t) => {
  const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-recommendation-origin-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_recommendation_snapshot;const provider=spec.providers.cross_border;const contract=provider.api_contract;const id='100';const valid={code:0,data:{items:[{apply_entity:{id},content:{meta:{campaign_id:id}}}],summary:{count:1}}};assert.equal(recommendation.recommendationData(valid,contract,id).items.length,1);
  for(const mutate of [(value)=>delete value.data.items[0].apply_entity.id,(value)=>value.data.items[0].apply_entity.id='9',(value)=>delete value.data.items[0].content.meta.campaign_id,(value)=>value.data.items[0].content.meta.campaign_id='9']){const value=structuredClone(valid);mutate(value);assert.throws(()=>recommendation.recommendationData(value,contract,id),{code:JSON.stringify(value).includes('"9"')?'campaign_recommendation_plan_conflict':'campaign_recommendation_shape_invalid'});}for(const value of [{code:0,data:{items:{},summary:{}}},{code:0,data:{items:[],summary:[]}}])assert.throws(()=>recommendation.recommendationData(value,contract,id),{code:'campaign_recommendation_shape_invalid'});
  let execution=0;async function execute(targetEndpoint,mutate,disconnect=false){execution+=1;let connected=true;const page={url:()=>`${provider.response_origin}/homepage`,request:{fetch:async(url,options)=>{const original=new URL(url),final=new URL(url);if(original.pathname===targetEndpoint)mutate?.(final);if(disconnect)connected=false;const body=original.pathname===contract.campaign_endpoint?pageBody():valid;return fetchResponse(final.href,body);}}};const context={pages:()=>[page]},browser={isConnected:()=>connected,contexts:()=>[context]};return recommendation.run(input(spec,path.join(root,`stage-${execution}`)),{browser,browserContext:context,skillRoot:path.resolve(__dirname,'..'),clock:()=>new Date('2026-08-21T00:00:00Z')});}
  for(const endpoint of [contract.campaign_endpoint,contract.recommendation_endpoint]){for(const origin of ['https://evil.example','https://seller-ph.tiktok.com'])await assert.rejects(()=>execute(endpoint,(url)=>{const changed=new URL(origin);url.protocol=changed.protocol;url.host=changed.host;}),{code:'seller_origin_mismatch'});await assert.rejects(()=>execute(endpoint,(url)=>url.pathname='/wrong'),{code:'seller_origin_mismatch'});for(const field of [contract.request_query.seller,contract.request_query.advertiser]){await assert.rejects(()=>execute(endpoint,(url)=>url.searchParams.delete(field)),{code:'provider_binding_invalid'});await assert.rejects(()=>execute(endpoint,(url)=>url.searchParams.set(field,'9')),{code:'provider_binding_invalid'});}}
  for(const field of Object.values(contract.recommendation_request_fields)){await assert.rejects(()=>execute(contract.recommendation_endpoint,(url)=>url.searchParams.delete(field)),{code:'campaign_recommendation_request_scope_invalid'});await assert.rejects(()=>execute(contract.recommendation_endpoint,(url)=>url.searchParams.set(field,'9')),{code:'campaign_recommendation_request_scope_invalid'});}await assert.rejects(()=>execute(contract.campaign_endpoint,null,true),{code:'browser_disconnected'});
});

test('change log uses the visible campaign table, trusts raw-zero shape, and paginates positive logs',async(t)=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'batch-g-change-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));const spec=loadReportMd().specs.gmvmax_campaign_change_log,c=spec.providers.cross_border.api_contract;const seen=[];const live=harness(async(url,options)=>{const u=new URL(url);seen.push({u,options});const page=options.data.page;return fetchResponse(url,{code:0,data:{logs:[{id:`log-${page}`,future:true}],pagination:{total_count:2,page_count:2,page}}});});const current=[campaign({campaign_id:'100',campaign_name:'  Ｃａｍｐ   Name  '})];const result=await changeLog.run(input(spec,path.join(root,'positive'),{campaignRef:' Camp Name '}),{...live.dependencies,discoverCampaigns:async()=>current});assert.equal(result.artifacts[0].row_count,2);assert.deepEqual(seen.map((x)=>x.options.method),[c.methods.change,c.methods.change]);for(const x of seen){assert.equal(x.u.searchParams.get(c.request_query.seller),SELLER);assert.equal(x.u.searchParams.get(c.request_query.advertiser),ADVERTISER);}const zeroLive=harness(async(url)=>fetchResponse(url,{code:0,data:{pagination:{total_count:0,page_count:0,page:1}}}));const zero=await changeLog.run(input(spec,path.join(root,'zero')),{...zeroLive.dependencies,discoverCampaigns:async()=>[campaign()]});assert.equal(zero.artifacts[0].status,'no_data');assert.equal(zero.artifacts[0].row_count,0);assert.equal(fs.existsSync(zero.artifacts[0].output_file),true);assert.equal(require('../scripts/common/xlsx_first_sheet').readFirstWorksheet(fs.readFileSync(zero.artifacts[0].output_file)).rows.length,1);
  async function rejected(name,change,status=200,mutate){let connected=true;const h=harness(async(url,options)=>{let final=new URL(url);mutate?.(final);if(change==='disconnect'){connected=false;throw new Error('x');}const page=options.data.page,body=change==='duplicate'?{code:0,data:{logs:[{id:'x'},{id:'x'}],pagination:{total_count:2,page_count:1,page:1}}}:change==='drift'?{code:0,data:{logs:[{id:`x${page}`}],pagination:{total_count:page===1?2:3,page_count:2,page}}}:{code:0,data:{pagination:{total_count:0,page_count:0,page:1}}};return fetchResponse(final.href,body,status);});const browser={isConnected:()=>connected,contexts:()=>[h.context]};return changeLog.run(input(spec,path.join(root,name)),{...h.dependencies,browser,discoverCampaigns:async()=>[campaign()]});}
  await assert.rejects(()=>rejected('duplicate','duplicate'),{code:'campaign_change_log_pagination_incomplete'});await assert.rejects(()=>rejected('drift','drift'),{code:'campaign_change_log_pagination_incomplete'});for(const o of ['https://evil.example','https://seller-ph.tiktok.com'])await assert.rejects(()=>rejected(new URL(o).hostname,'zero',200,(u)=>{const v=new URL(o);u.protocol=v.protocol;u.host=v.host;}),{code:'seller_origin_mismatch'});await assert.rejects(()=>rejected('locale','zero',200,(u)=>u.searchParams.delete('locale')),{code:'provider_binding_invalid'});await assert.rejects(()=>rejected('403','zero',403),{code:'transport_login_required'});await assert.rejects(()=>rejected('disconnect','disconnect'),{code:'browser_disconnected'});
});

