test('hourly zero and malformed shapes fail closed without inventing hours', async () => {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'batch-g-hourly-zero-')); const spec = loadReportMd().specs.gmvmax_campaign_hourly_performance; const live = harness();
  const zero = await hourly.run(input(spec, path.join(root, 'zero')), { ...live.dependencies, request: async (_page, request) => new URL(request.url).pathname.endsWith('post_campaign_list') ? ok(pageBody()) : ok({ code: 0, data: null }) });
  assert.equal(zero.artifacts[0].status, 'no_data'); assert.equal(zero.artifacts[0].row_count, 0);
  await assert.rejects(() => hourly.run(input(spec, path.join(root, 'bad-categories')), { ...live.dependencies, request: async (_page, request) => new URL(request.url).pathname.endsWith('post_campaign_list') ? ok(pageBody()) : ok({ code: 0, data: { chart: { categories: ['00:00'], series: [{name:'cost',data:[1]}] } } }) }), { code: 'campaign_hourly_shape_invalid' });
  await assert.rejects(() => hourly.run(input(spec, path.join(root, 'bad-series')), { ...live.dependencies, request: async (_page, request) => new URL(request.url).pathname.endsWith('post_campaign_list') ? ok(pageBody()) : ok({ code: 0, data: { chart: { categories: hourlyChart().data.chart.categories, series: [{name:'cost',data:Array(23).fill(1)}] } } }) }), { code: 'campaign_hourly_shape_invalid' });
  const requested=spec.providers.cross_border.api_contract.hourly_request.query_list;await assert.rejects(() => hourly.run(input(spec, path.join(root, 'missing-requested-series')), { ...live.dependencies, request: async (_page, request) => new URL(request.url).pathname.endsWith('post_campaign_list') ? ok(pageBody()) : ok(hourlyChart(requested.slice(1))) }), { code: 'campaign_hourly_shape_invalid' });
  const booleanMetric=hourlyChart(requested,()=>1);booleanMetric.data.chart.series.find((item)=>item.name==='show_cnt').data[0]=true;
  await assert.rejects(() => hourly.run(input(spec, path.join(root, 'boolean-target')), { ...live.dependencies, request: async (_page, request) => new URL(request.url).pathname.endsWith('post_campaign_list') ? ok(pageBody()) : ok(booleanMetric) }), { code: 'campaign_hourly_shape_invalid' });
});

